from rich.console import Console
from rich.prompt import Prompt, InvalidResponse

class MyPrompt(Prompt):
    def validate_response(self, response):
        if response != "yes":
            raise InvalidResponse("[red]Invalid response![/red]")
        return response

console = Console(markup=False)
prompt = MyPrompt(console=console)

try:
    # We need to simulate the prompt call. 
    # Since Prompt.__call__ reads from stdin, we can mock it or just call the method that triggers on_validate_error.
    # But it's easier to just call on_validate_error directly.
    prompt.on_validate_error("no", InvalidResponse("[red]Invalid response![/red]"))
except Exception as e:
    print(e)
